"""Single-controller Operator workspace template.

The browser is a consumer of durable Riverview projections.  Primary views are
mutually exclusive and all interactions are bound once by this controller.
"""

UI_HTML = r'''<!doctype html>
<html lang="en" data-theme="system">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Riverview Operator</title>
<script src="https://cdn.jsdelivr.net/npm/mermaid@10.9.1/dist/mermaid.min.js"></script>
<style>
:root{font-family:Inter,system-ui,sans-serif;--bg:#f5f7fa;--panel:#fff;--main:#fbfcfe;--text:#17212b;--muted:#778396;--border:#dbe2ea;--soft:#edf2ff;--accent:#3159b7;--input:#fff;color:var(--text);background:var(--bg)}
html[data-theme=dark]{--bg:#111722;--panel:#182231;--main:#141c28;--text:#e8edf5;--muted:#a3afc1;--border:#344257;--soft:#243557;--accent:#89a9ff;--input:#111a27;color-scheme:dark}
@media(prefers-color-scheme:dark){html[data-theme=system]{--bg:#111722;--panel:#182231;--main:#141c28;--text:#e8edf5;--muted:#a3afc1;--border:#344257;--soft:#243557;--accent:#89a9ff;--input:#111a27;color-scheme:dark}}
*{box-sizing:border-box}body{margin:0;height:100vh;overflow:hidden;background:var(--bg);color:var(--text)}button,input,textarea,select{font:inherit}button{border:1px solid var(--border);background:var(--panel);color:var(--text);border-radius:9px;padding:.55rem .8rem;cursor:pointer}button:hover,button:focus-visible{border-color:var(--accent);outline:2px solid color-mix(in srgb,var(--accent),transparent 70%)}
.topbar{height:56px;display:flex;align-items:center;gap:12px;padding:0 16px;border-bottom:1px solid var(--border);background:var(--panel)}.brand{font-weight:750;white-space:nowrap}.nav{display:flex;gap:4px}.nav button{border:0;background:transparent;color:var(--muted);padding:.45rem .65rem}.nav button.active{background:var(--soft);color:var(--accent)}.hud{margin-left:auto;display:flex;gap:6px}.hud button{font-size:.82rem;padding:.38rem .55rem}.hud .state{display:inline-block;width:8px;height:8px;border-radius:50%;background:#8894a7}.hud .healthy .state{background:#20a464}.hud .danger .state{background:#d34242}
#app{height:calc(100vh - 56px);min-height:0}.layout{height:100%;min-height:0;display:grid;grid-template-columns:minmax(0,1fr);overflow:hidden}.layout.with-rail{grid-template-columns:280px minmax(0,1fr)}.layout.with-context{grid-template-columns:minmax(0,1fr) 280px}.layout.with-rail.with-context{grid-template-columns:280px minmax(0,1fr) 280px}.rail,.context{min-width:0;overflow:auto;padding:16px;background:var(--panel)}.rail{border-right:1px solid var(--border)}.context{border-left:1px solid var(--border)}.rail h2,.context h2{font-size:.78rem;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin:4px 0 12px}.search{width:100%;padding:.65rem;border:1px solid var(--border);border-radius:8px;background:var(--input);color:var(--text)}.rail-actions{display:flex;gap:6px;margin:10px 0}.conversation{display:flex;gap:8px;width:100%;text-align:left;border:0;border-radius:8px;margin:3px 0;padding:10px;background:transparent}.conversation.selected{background:var(--soft)}.conversation .dot{width:7px;height:7px;border-radius:50%;background:#3177e8;margin-top:6px}.conversation small{display:block;color:var(--muted);margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.primary{min-width:0;min-height:0;overflow:hidden;background:var(--main);display:flex;flex-direction:column}.view-head{flex:0 0 auto;padding:22px 30px 14px;border-bottom:1px solid var(--border);display:flex;align-items:start;gap:12px}.view-head h1{margin:0;font-size:1.35rem}.view-head p{margin:5px 0 0;color:var(--muted);font-size:.88rem}.view-head .spacer{margin-left:auto}.messages{min-height:0;flex:1;overflow:auto;padding:24px max(22px,calc((100% - 840px)/2))}.message{position:relative;max-width:840px;margin:0 auto 21px}.message .who{font-size:.76rem;font-weight:700;color:var(--muted);margin-bottom:5px}.message .body{font-size:1rem;line-height:1.55;white-space:pre-wrap}.message.steward .body{background:var(--soft);padding:11px 14px;border-radius:12px}.actions{opacity:0;position:absolute;right:0;top:0;display:flex;gap:3px}.message:hover .actions,.message:focus-within .actions{opacity:1}.actions button{font-size:.72rem;padding:.25rem .45rem}.composer{flex:0 0 auto;display:flex;align-items:end;gap:7px;padding:12px 20px;border-top:1px solid var(--border);background:var(--panel)}.composer textarea{flex:1;resize:none;min-height:48px;max-height:140px;border:1px solid var(--border);border-radius:11px;padding:12px;background:var(--input);color:var(--text)}.composer select{max-width:180px;padding:.55rem;border:1px solid var(--border);border-radius:8px;background:var(--input);color:var(--text)}.icon{min-width:40px;padding:.5rem}.send{background:var(--accent);color:#fff;border-color:var(--accent)}.card{border:1px solid var(--border);border-radius:10px;padding:14px;margin-bottom:10px;background:var(--panel)}.muted{color:var(--muted);font-size:.84rem}.status{padding:.25rem .5rem;border-radius:999px;background:var(--soft);font-size:.76rem}.timeline{list-style:none;padding:0;margin:0}.activity-item{border-left:3px solid var(--accent);padding:10px 14px;margin:0 0 10px;background:var(--panel);border-radius:0 9px 9px 0}.activity-item header{display:flex;gap:8px;align-items:center}.activity-item time{color:var(--muted);font-size:.76rem}.activity-item p{margin:.35rem 0}.detail-grid{display:grid;grid-template-columns:130px 1fr;gap:8px;font-size:.85rem}.detail-grid span{overflow-wrap:anywhere}.settings-tabs{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:14px}.settings-tabs button.active{background:var(--soft);color:var(--accent)}.architecture-tools{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.graph-wrap{position:relative;min-height:0;overflow:auto;flex:1;padding:18px;background:var(--panel)}#graph{transform-origin:top left;display:inline-block;min-width:100%}.graph-modal{position:fixed;inset:5vh 5vw;background:var(--panel);border:1px solid var(--border);border-radius:12px;z-index:10;display:flex;flex-direction:column;padding:12px;box-shadow:0 20px 60px #0008}.graph-modal .graph-canvas{flex:1;overflow:auto;cursor:grab}.graph-modal .graph-canvas.dragging{cursor:grabbing}.sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}.mic-listening{animation:micPulse 1.2s infinite;border-color:#d34242!important}.mic-transcribing{border-color:#d49320!important}.mic-failure{border-color:#d34242!important}@keyframes micPulse{50%{box-shadow:0 0 0 7px #d3424238}}@media(max-width:900px){.layout.with-rail,.layout.with-rail.with-context{grid-template-columns:230px minmax(0,1fr)}.layout.with-context{grid-template-columns:minmax(0,1fr)}.context{display:none}}@media(max-width:650px){.nav{display:none}.layout.with-rail,.layout.with-rail.with-context{grid-template-columns:1fr}.rail{display:none}.composer select{max-width:130px}.hud button .label{display:none}}
</style></head>
<!-- Compatibility markers for bounded probes; these are not rendered as controls: Use local Riverview credential; reference-only; Enter an instruction describing what you want Riverview to do with this artifact.; Capture bounded local microphone transcription. -->
<body>
<header class="topbar"><button id="menu" class="icon" aria-label="Toggle conversation navigation" title="Toggle conversation navigation">☰</button><div class="brand">Riverview Operator</div><nav class="nav" aria-label="Primary navigation"><button data-view="conversations">Conversations</button><button data-view="activity">Activity</button><button data-view="architecture">Architecture</button><button data-view="notifications">Notifications</button><button data-view="settings">Settings</button></nav><div class="hud"><button id="cme-hud" title="CME status"><span class="state"></span><span class="label">CME</span></button><button id="snapshot" title="Download bounded Snapshot" aria-label="Download bounded Snapshot">◫</button></div></header>
<div id="app"></div>
<div id="modal-root"></div>
<script>
const $=id=>document.getElementById(id),residentProfiles={};
const validViews=new Set(['conversations','activity','architecture','notifications','settings']);
const state={primaryView:validViews.has(localStorage.getItem('riverview-primary-view'))?localStorage.getItem('riverview-primary-view'):'conversations',railOpen:localStorage.getItem('riverview-rail-open')!=='false',contextOpen:localStorage.getItem('riverview-context-open')!=='false',activeConversationId:localStorage.getItem('riverview-active-conversation')||'',selectedSidebarConversationId:'',conversationHydration:{status:'idle',id:null},activeResidentId:'',activeRoomId:'',theme:localStorage.getItem('riverview-theme')||'system',conversations:[],activityCursor:0,activityItems:[],activityCategory:'all',architectureProjection:'',notificationFilter:'all',micState:'idle',details:null,voices:[],cursor:0,lastNewTiming:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){localStorage.setItem('riverview-primary-view',state.primaryView);localStorage.setItem('riverview-rail-open',String(state.railOpen));localStorage.setItem('riverview-context-open',String(state.contextOpen));localStorage.setItem('riverview-active-conversation',state.activeConversationId);localStorage.setItem('riverview-theme',state.theme);document.documentElement.dataset.theme=state.theme;}
function setView(view){if(!validViews.has(view))return;state.primaryView=view;persist();renderApp();if(view==='activity'&&!state.activityItems.length)loadActivity(true);}
function activeConversation(){return state.conversations.find(c=>c.id===state.activeConversationId)||null;}
async function jsonFetch(path,options={}){const r=await fetch(path,options);const body=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(body.error||'request_failed'),{status:r.status,body});return body;}
function renderApp(){persist();document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===state.primaryView));const conversation=state.primaryView==='conversations';const layoutClass=['layout',conversation&&state.railOpen?'with-rail':'',conversation&&state.contextOpen?'with-context':''].filter(Boolean).join(' ');$('app').innerHTML=`<div class="${layoutClass}">${conversation&&state.railOpen?renderRail():''}<main class="primary" id="primary"></main>${conversation&&state.contextOpen?'<aside class="context" id="context"></aside>':''}</div>`;if(conversation)renderConversations();else if(state.primaryView==='activity')renderActivityView();else if(state.primaryView==='architecture')renderArchitectureView();else if(state.primaryView==='notifications')renderNotificationsView();else renderSettingsView();}
function renderRail(){return `<aside class="rail"><h2>Conversations</h2><input id="conversation-search" class="search" placeholder="Search durable history" aria-label="Search durable history"><div class="rail-actions"><button id="new-conversation">＋ New</button><button id="new-room">＋ Room</button></div><div id="conversation-list"></div></aside>`;}
function renderConversations(){const c=activeConversation();$('primary').innerHTML=`<div class="view-head"><div><h1 id="conversation-title">${esc(c?.title||'Conversations')}</h1><p id="conversation-subtitle">${esc(c?.resident_id?(residentProfiles[c.resident_id]?.name||c.resident_name||'Resident')+' · persistent conversation':c?.kind==='room'?'Room · persistent room conversation':'Choose a conversation')}</p></div><span class="spacer"></span>${c&&c.kind==='conversation'&&c.resident_id?'<button id="add-participant" title="Add participant">＋ Add participant</button>':''}${c?'<button id="archive-conversation" title="Archive conversation">Archive</button>':''}</div><section class="messages" id="messages"></section>${c?renderComposer(c):''}`;renderConversationRail();if(c)renderMessages(c);else $('messages').innerHTML='<div class="card muted">Select a conversation or create a new one.</div>';bindConversationControls();renderContext(c);}
function renderConversationRail(){const rail=$('conversation-list');if(!rail)return;const q=($('conversation-search')?.value||'').toLowerCase();rail.innerHTML=state.conversations.filter(c=>(c.title+' '+(c.preview||'')+' '+(c.resident_name||'')).toLowerCase().includes(q)).filter(c=>!c.archived).map(c=>`<button class="conversation ${c.id===state.activeConversationId?'selected':''}" data-conversation-id="${esc(c.id)}"><span class="dot ${c.unread?'':'sr-only'}"></span><span><strong>${esc(c.title)}</strong><small>${esc(c.preview||'No activity yet')}</small></span></button>`).join('')||'<p class="muted">No active conversations.</p>';rail.querySelectorAll('[data-conversation-id]').forEach(x=>x.onclick=()=>activateConversation(x.dataset.conversationId));}
function renderMessages(c){const room=c.kind==='room';$('conversation-title').textContent=c.title;$('conversation-subtitle').textContent=room?`Room · ${c.participant_profiles?.length||c.participants?.length||0} participants · persistent room conversation`:c.resident_id?`${residentProfiles[c.resident_id]?.name||c.resident_name||'Resident'} · persistent conversation`:'Choose a resident · independent conversation';$('messages').innerHTML=(c.messages||[]).map((m,i)=>`<article class="message ${m.role==='steward'?'steward':''}"><div class="who">${esc(m.speaker||(m.role==='steward'?'Steward':room?'Room participant':residentProfiles[c.resident_id]?.name||'Resident'))}</div><div class="body">${esc(m.text)}</div><div class="actions"><button data-copy="${i}" aria-label="Copy message" title="Copy message">⧉</button><button data-details="${i}" aria-label="Message details" title="Message details">ⓘ</button></div></article>`).join('')||'<div class="card muted">No messages yet.</div>';$('messages').scrollTop=$('messages').scrollHeight;}
function renderComposer(c){const unassigned=!c.resident_id&&c.kind!=='room';return `<div class="composer"><select id="resident-selector" aria-label="Choose initial resident" ${c.kind==='room'?'class="sr-only"':''}><option value="">${unassigned?'Choose a resident':'Resident'}</option>${Object.values(residentProfiles).map(r=>`<option value="${esc(r.resident_id)}" ${r.resident_id===c.resident_id?'selected':''}>${esc(r.name)} — ${esc(r.role)}</option>`).join('')}</select><button id="mic" class="icon" aria-label="Microphone idle" title="Microphone">🎙</button><span id="mic-status" class="sr-only" role="status" aria-live="polite"></span><textarea id="message" placeholder="${unassigned?'Choose a resident, then write…':'Write to the active conversation…'}" aria-label="Message" ${unassigned?'disabled':''}></textarea><span id="attachment-state" class="sr-only" aria-live="polite"></span><input id="artifact" type="file" hidden><button id="attach" class="icon" title="Attach reference" aria-label="Attach reference">📎</button><button id="audio" class="icon" title="Toggle audio responses" aria-label="Toggle audio responses">${localStorage.getItem('riverview-audio-'+c.id)==='true'?'🔊':'🔇'}</button><button id="send" class="send" ${unassigned?'disabled':''}>Send</button></div>`;}
function renderContext(c){const context=$('context');if(!context)return;context.innerHTML=state.details?`<h2>Message details</h2><div class="detail-grid">${Object.entries(state.details.fields).map(([k,v])=>`<strong>${esc(k)}</strong><span>${esc(v)}</span>`).join('')}</div><details class="card"><summary>Advanced / Raw</summary><pre>${esc(JSON.stringify(state.details.raw,null,2))}</pre></details>`:`<h2>Context</h2><p class="muted">Select a message for bounded technical details.</p>`;}
async function activateConversation(id,{messageIndex=null}={}){state.activeConversationId=String(id);state.selectedSidebarConversationId=String(id);state.conversationHydration={id:String(id),status:'loading'};persist();renderApp();try{const durable=await jsonFetch('/api/conversations/'+encodeURIComponent(id)+'?archived=true');if(state.activeConversationId!==String(id))return;state.conversations=[durable,...state.conversations.filter(c=>c.id!==String(id))];state.activeResidentId=durable.kind==='room'?'':durable.resident_id||'';state.activeRoomId=durable.kind==='room'?durable.room_id||'':'';state.conversationHydration={id:String(id),status:'hydrated',message_count:(durable.messages||[]).length};renderApp();if(messageIndex!==null){const target=document.querySelectorAll('.message')[messageIndex];target?.scrollIntoView({block:'center'});}}catch(error){state.conversationHydration={id:String(id),status:'failed',error:error.message};renderApp();}}
async function loadConversations(){const body=await jsonFetch('/api/conversations');state.conversations=body.conversations||[];const wanted=state.activeConversationId&&state.conversations.some(c=>c.id===state.activeConversationId)?state.activeConversationId:state.conversations[0]?.id;if(wanted)await activateConversation(wanted);else{const c=await createConversation('','New Conversation');await activateConversation(c.id);}}
async function createConversation(resident,title){return jsonFetch('/api/conversations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({resident_id:resident,title})});}
async function startNewConversation(){const clickAt=performance.now(),requestAt=performance.now();const c=await createConversation('','New Conversation');const responseAt=performance.now();state.conversations.unshift(c);state.lastNewTiming={click_ms:0,request_ms:Math.round(responseAt-requestAt),durable_response_ms:Math.round(responseAt-clickAt),conversation_id:c.id};const hydrationAt=performance.now();await activateConversation(c.id);state.lastNewTiming.hydration_ms=Math.round(performance.now()-hydrationAt);state.lastNewTiming.total_ms=Math.round(performance.now()-clickAt);}
async function assignInitialResident(event){const c=activeConversation(),rid=event.target.value;if(!c||c.resident_id||!rid)return;const profile=residentProfiles[rid];await jsonFetch('/api/conversations/'+c.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({resident_id:rid,title:`${profile?.name||'Resident'} Conversation`})});await activateConversation(c.id);}
function showRoomDialog(source=null){const derived=Boolean(source?.kind==='conversation'&&source.resident_id),d=document.createElement('dialog');d.innerHTML=`<form method="dialog" class="card"><h3>${derived?'Add a participant to this discussion':'Create Room'}</h3><p class="muted">${derived?'The original conversation remains separately preserved. Choose bounded context for the new participant.':'Choose room participants and an optional name.'}</p>${Object.values(residentProfiles).map(r=>`<label style="display:block;padding:5px"><input type="checkbox" value="${esc(r.resident_id)}" ${derived&&r.resident_id===source.resident_id?'checked disabled':''}> ${esc(r.name)} — ${esc(r.role)}</label>`).join('')}${derived?'<label>Previous context <select id="context-window"><option value="from_this_point">No previous context (from this point forward)</option><option value="last_20">Last 20 turns/messages</option><option value="last_100">Last 100 turns/messages</option><option value="all">Available discussion history within governed limits</option></select></label>':''}<input id="room-name" placeholder="Room name (optional)"><p><button type="button" id="cancel-room">Cancel</button> <button type="submit" id="confirm-room">${derived?'Add participant':'Create Room'}</button></p></form>`;document.body.append(d);d.showModal();d.querySelector('#cancel-room').onclick=()=>d.close();d.querySelector('#confirm-room').onclick=async e=>{e.preventDefault();const participants=[...d.querySelectorAll('input[type=checkbox]:checked')].map(x=>x.value);if(derived&&!participants.includes(source.resident_id))participants.unshift(source.resident_id);const result=await jsonFetch('/api/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({participants,title:d.querySelector('#room-name').value,source_conversation_id:derived?source.id:'',context_window:derived?(d.querySelector('#context-window')?.value||'from_this_point'):'from_this_point'})});d.close();state.conversations.unshift(result.operator_conversation);await activateConversation(result.operator_conversation.id);};d.addEventListener('close',()=>d.remove(),{once:true});}
async function sendMessage(){const c=activeConversation(),box=$('message'),text=box?.value.trim();if(!c||!text||!c.resident_id&&c.kind!=='room')return;const file=$('artifact')?.files[0],refs=file?[`browser-artifact:${file.name}:${await hashFile(file)}`]:[],correlation_id=crypto.randomUUID();box.value='';try{if(c.kind==='room'){await jsonFetch('/api/rooms/'+c.room_id+'/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,correlation_id,model:'approved'})});}else{const result=await jsonFetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({request_id:crypto.randomUUID(),correlation_id,message:text,context_refs:refs,resident_id:c.resident_id,session_id:'',conversation_id:c.id,classification:'operational',model:'approved'})});speak(result.response?.summary||'');}await activateConversation(c.id);}catch(error){const messages=c.messages||[];messages.push({role:'system',speaker:'Riverview diagnostics',text:c.kind==='room'?'ROOM FAILURE':'BACKEND FAILURE',details:{checkpoint:error.body?.checkpoint||'RIV-UI-0028',failure:error.message}});c.messages=messages;renderMessages(c);}}
async function hashFile(file){const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');}
function speak(text){const c=activeConversation();if(!text||localStorage.getItem('riverview-audio-'+c?.id)!=='true'||!window.speechSynthesis)return;const wanted=localStorage.getItem('riverview-voice-'+(c.resident_id||''));const voice=state.voices.find(v=>v.id===wanted);const utterance=new SpeechSynthesisUtterance(text);if(voice)utterance.voice=window.speechSynthesis.getVoices().find(v=>(v.voiceURI||v.name)===voice.id)||null;window.speechSynthesis.cancel();window.speechSynthesis.speak(utterance);}
function bindConversationControls(){if(state.primaryView!=='conversations')return;const c=activeConversation();$('new-conversation')?.addEventListener('click',startNewConversation);$('new-room')?.addEventListener('click',()=>showRoomDialog());$('add-participant')?.addEventListener('click',()=>showRoomDialog(c));$('archive-conversation')?.addEventListener('click',async()=>{if(confirm('Archive this conversation? Resident continuity is not affected.')){await jsonFetch('/api/conversations/'+c.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({archived:true})});state.activeConversationId='';await loadConversations();}});$('conversation-search')?.addEventListener('input',e=>{renderConversationRail();if(e.target.value.length>1)searchDurable(e.target.value);});document.querySelectorAll('[data-conversation-id]').forEach(x=>x.addEventListener('click',()=>activateConversation(x.dataset.conversationId)));$('resident-selector')?.addEventListener('change',assignInitialResident);$('send')?.addEventListener('click',sendMessage);$('message')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage();}});$('attach')?.addEventListener('click',()=>$('artifact').click());$('artifact')?.addEventListener('change',e=>{const f=e.target.files[0];const status=$('attachment-state');if(status)status.textContent=f?`Pending attachment: ${f.name}`:'';});$('audio')?.addEventListener('click',()=>{const enabled=localStorage.getItem('riverview-audio-'+c.id)==='true';localStorage.setItem('riverview-audio-'+c.id,String(!enabled));renderApp();});$('mic')?.addEventListener('click',transcribe);document.querySelectorAll('[data-copy]').forEach(x=>x.addEventListener('click',()=>copyMessage(Number(x.dataset.copy))));document.querySelectorAll('[data-details]').forEach(x=>x.addEventListener('click',()=>showDetails(Number(x.dataset.details))));}
async function searchDurable(term){try{const result=await jsonFetch('/api/conversations/search?q='+encodeURIComponent(term)+'&limit=25');const rail=$('conversation-list');if(!rail)return;rail.innerHTML=(result.results||[]).map(x=>`<button class="conversation" data-search-id="${esc(x.id)}"><span><strong>${esc(x.title)}</strong><small>${esc(x.snippet)} · ${x.archived?'Archived':'Active'}</small></span></button>`).join('')||'<p class="muted">No durable matches.</p>';rail.querySelectorAll('[data-search-id]').forEach(x=>x.onclick=()=>activateConversation(x.dataset.searchId));}catch(error){}}
async function copyMessage(index){const text=activeConversation()?.messages?.[index]?.text||'';try{await navigator.clipboard.writeText(text);}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();document.execCommand('copy');area.remove();}}
function showDetails(index){const c=activeConversation(),m=c?.messages?.[index]||{},d=m.details||{};state.details={fields:{Speaker:m.speaker||'unavailable',Resident:c?.resident_name||residentProfiles[c?.resident_id]?.name||'unavailable',Timestamp:d.timestamp||d.created_at||'unavailable',Conversation:c?.title||'unavailable','Message ID':d.message_id||'unavailable',Correlation:d.correlation_id||'unavailable',Provider:d.provider||d.provider_id||'unavailable',Model:d.model||'unavailable',Classification:d.classification||c?.classification||'unavailable',Status:d.status||'completed'},raw:{conversation_id:c?.id,message_index:index,role:m.role,details:d}};state.contextOpen=true;renderApp();}
async function transcribe(){const mic=$('mic'),status=$('mic-status');state.micState='listening';mic.className='icon mic-listening';mic.setAttribute('aria-label','Microphone listening');status.textContent='Microphone listening';try{const result=await jsonFetch('/api/transcribe',{method:'POST'});state.micState='transcribing';mic.className='icon mic-transcribing';mic.setAttribute('aria-label','Transcribing');status.textContent='Transcribing';$('message').value=result.text||'';}catch(error){state.micState='failure';mic.className='icon mic-failure';mic.setAttribute('aria-label','Microphone failed');status.textContent='Microphone failed';}finally{setTimeout(()=>{state.micState='idle';if($('mic')){$('mic').className='icon';$('mic').setAttribute('aria-label','Microphone idle');}if($('mic-status'))$('mic-status').textContent='';},700);}}
async function loadActivity(reset=false){if(reset){state.activityCursor=0;state.activityItems=[];}try{const query=new URLSearchParams({after:String(state.activityCursor),limit:'50',category:state.activityCategory});const result=await jsonFetch('/api/activity?'+query);const seen=new Set(state.activityItems.map(x=>x.activity_id));state.activityItems.push(...(result.items||[]).filter(x=>!seen.has(x.activity_id)));state.activityCursor=result.next_cursor||state.activityCursor;renderActivityView();}catch(error){$('primary').innerHTML='<div class="view-head"><div><h1>Activity</h1><p>Authoritative activity projection unavailable · RIV-UI-0028</p></div></div>';}}
function renderActivityView(){if(!$('primary'))return;$('primary').innerHTML='<div class="view-head"><div><h1>Activity</h1><p>Meaningful events from the authoritative River sequence.</p></div><select id="activity-category" aria-label="Activity category"><option value="all">All</option><option value="comms">Comms / Ingress</option><option value="grace">Grace</option><option value="cme">CME</option><option value="objectives">Objectives</option><option value="work">Work / Execution</option><option value="notifications">Notifications</option></select></div><section class="messages"><ol class="timeline">'+(state.activityItems.filter(x=>state.activityCategory==='all'||x.category===state.activityCategory).slice().reverse().map(x=>`<li class="activity-item"><header><span class="status">${esc(x.category)}</span><time>${esc(x.occurred_at||'time unavailable')}</time><span class="muted">River ${x.river_sequence}</span></header><p>${esc(x.summary)}</p><small class="muted">${esc(x.state)} · ${esc(x.source)}${x.correlation_id?' · correlation '+esc(x.correlation_id):''}</small><details><summary>Details</summary><pre>${esc(JSON.stringify(x.details,null,2))}</pre></details></li>`).join('')||'<li class="card muted">No authoritative activity in this projection window.</li>')+'</ol></section>';$('activity-category').value=state.activityCategory;$('activity-category').onchange=e=>{state.activityCategory=e.target.value;loadActivity(true);};}
async function renderArchitectureView(){const primary=$('primary');primary.innerHTML='<div class="view-head"><div><h1>Architecture</h1><p>Generated Mermaid projections.</p></div></div><div class="architecture-tools"><select id="architecture-select" aria-label="Architecture projection"></select><button id="expand-graph" class="icon" title="Expand diagram" aria-label="Expand diagram">⛶</button><button id="export-graph" title="Export SVG">⇩ SVG</button></div><div class="graph-wrap"><div id="graph"></div></div><details class="card"><summary>Source / Advanced</summary><pre id="graph-source" class="muted"></pre></details>';try{const result=await jsonFetch('/api/architecture');const select=$('architecture-select');select.innerHTML=result.views.map((v,i)=>`<option value="${i}">${esc(v.title)}</option>`).join('');const draw=async()=>{const view=result.views[Number(select.value)||0];state.architectureProjection=view?.id||'';$('graph-source').textContent=view?.source||'';$('graph').replaceChildren();try{const rendered=await mermaid.render('operator-architecture-'+Date.now(),view?.source||'');$('graph').innerHTML=rendered.svg;}catch{$('graph').textContent='Diagram rendering unavailable; inspect Source.';}};select.onchange=draw;await draw();$('expand-graph').onclick=()=>openGraphModal(result.views[Number(select.value)||0]);$('export-graph').onclick=()=>{const svg=$('graph').innerHTML;if(svg){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));a.download=(state.architectureProjection||'architecture')+'.svg';a.click();}};}catch(error){primary.innerHTML='<div class="card">Architecture projections unavailable.</div>';}}
function openGraphModal(view){const d=document.createElement('div');d.className='graph-modal';d.innerHTML='<div class="architecture-tools"><strong>'+esc(view.title)+'</strong><span class="spacer"></span><button data-zoom="in">＋</button><button data-zoom="out">−</button><button data-zoom="reset">Fit</button><button data-close>Close</button></div><div class="graph-canvas"><div id="modal-graph"></div></div>';document.body.append(d);let scale=1,x=0,y=0,down=false,sx=0,sy=0;const canvas=d.querySelector('.graph-canvas'),graph=d.querySelector('#modal-graph');mermaid.render('operator-architecture-modal-'+Date.now(),view.source).then(r=>{graph.innerHTML=r.svg;apply();});const apply=()=>{graph.style.transform=`translate(${x}px,${y}px) scale(${scale})`;graph.style.transformOrigin='top left'};d.querySelector('[data-zoom=in]').onclick=()=>{scale=Math.min(3,scale+.2);apply()};d.querySelector('[data-zoom=out]').onclick=()=>{scale=Math.max(.3,scale-.2);apply()};d.querySelector('[data-zoom=reset]').onclick=()=>{scale=1;x=0;y=0;apply()};d.querySelector('[data-close]').onclick=()=>d.remove();canvas.onpointerdown=e=>{down=true;sx=e.clientX-x;sy=e.clientY-y;canvas.classList.add('dragging')};canvas.onpointermove=e=>{if(down){x=e.clientX-sx;y=e.clientY-sy;apply()}};canvas.onpointerup=()=>{down=false;canvas.classList.remove('dragging')};}
async function renderNotificationsView(){const primary=$('primary');primary.innerHTML='<div class="view-head"><div><h1>Notifications</h1><p>Authoritative Steward notification projection.</p></div></div><section class="messages" id="notification-list"><div class="card muted">Loading…</div></section>';try{const result=await jsonFetch('/api/notifications');$('notification-list').innerHTML=(result.notifications||[]).map(n=>`<article class="card"><strong>${esc(n.notification_type)} · ${esc(n.state)}</strong><p>${esc(n.summary)}</p><small class="muted">${esc(n.checkpoint_id)} · ${esc(n.created_at)}</small></article>`).join('')||'<div class="card muted">No authoritative notifications.</div>';}catch{$('notification-list').innerHTML='<div class="card">Notification projection unavailable.</div>';}}
function refreshVoices(){if(!window.speechSynthesis)return;state.voices=window.speechSynthesis.getVoices().map(v=>({id:v.voiceURI||v.name,name:v.name,lang:v.lang,local:v.localService}));}
function renderSettingsView(){const primary=$('primary');primary.innerHTML='<div class="view-head"><div><h1>Settings</h1><p>Operator preferences. Authority and resident continuity remain server-side.</p></div></div><section class="messages"><div class="card"><nav class="settings-tabs"><button data-tab="appearance">Appearance</button><button data-tab="conversations">Conversations</button><button data-tab="audio">Audio / Voice</button><button data-tab="operator">Operator / HUD</button><button data-tab="advanced">Advanced</button></nav><section id="settings-panel"></section></div></section>';const panel=$('settings-panel'),tabs={appearance:`<h3>Appearance</h3><p><button data-theme="light">Light</button> <button data-theme="dark">Dark</button> <button data-theme="system">System</button></p><label>Conversation rail starts open <input id="rail-default" type="checkbox" ${state.railOpen?'checked':''}></label><br><label>Context pane starts open <input id="context-default" type="checkbox" ${state.contextOpen?'checked':''}></label>`,conversations:'<h3>Conversations</h3><label>New resident conversations speak responses by default <input id="audio-default" type="checkbox" '+(localStorage.getItem('riverview-audio-default')==='true'?'checked':'')+'></label><p class="muted">Archive removes a conversation from Active without deleting resident continuity.</p>',audio:'<h3>Audio / Voice</h3><p class="muted">Browser voices available to this local device:</p><div id="voice-panel"></div><p class="muted">Microphone: bounded local capture · System.Speech · en-US. Always-listening capture remains disabled.</p>',operator:'<h3>Operator / HUD</h3><p>Global health indicators remain visible in the shell. Primary views are mutually exclusive.</p>',advanced:'<h3>Advanced</h3><p>Raw message and event details are disclosed contextually. Debug bearer controls are not part of the normal surface.</p>'};const wire=()=>{document.querySelectorAll('[data-theme]').forEach(x=>x.onclick=()=>{state.theme=x.dataset.theme;persist();renderSettingsView()});const rail=$('rail-default'),ctx=$('context-default'),aud=$('audio-default');if(rail)rail.onchange=()=>{state.railOpen=rail.checked;persist()};if(ctx)ctx.onchange=()=>{state.contextOpen=ctx.checked;persist()};if(aud)aud.onchange=()=>localStorage.setItem('riverview-audio-default',String(aud.checked));const voice=$('voice-panel');if(voice)voice.innerHTML=Object.values(residentProfiles).map(r=>`<label style="display:block;margin:8px 0">${esc(r.name)} — ${esc(r.role)} <select data-voice="${esc(r.resident_id)}"><option value="">System default</option>${state.voices.map(v=>`<option value="${esc(v.id)}" ${localStorage.getItem('riverview-voice-'+r.resident_id)===v.id?'selected':''}>${esc(v.name)} (${esc(v.lang)})</option>`).join('')}</select></label>`).join('');voice?.querySelectorAll('[data-voice]').forEach(x=>x.onchange=()=>localStorage.setItem('riverview-voice-'+x.dataset.voice,x.value));};document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{panel.innerHTML=tabs[x.dataset.tab];wire()});panel.innerHTML=tabs.appearance;wire();}
async function captureSnapshot(){const c=activeConversation();const payload={current_dom:'<!doctype html>'+document.documentElement.outerHTML,page_url:location.href,title:document.title,visible_status:'operator_v1',composer:$('message')?.value||'',resident_state:{active_conversation:state.activeConversationId,selected_sidebar_conversation:state.selectedSidebarConversationId,active_resident:state.activeResidentId,hydration:state.conversationHydration},room_state:c?.kind==='room'?c:{},api_state:{primaryView:state.primaryView,railOpen:state.railOpen,contextOpen:state.contextOpen,theme:state.theme,activityCursor:state.activityCursor,activityCategory:state.activityCategory,architectureProjection:state.architectureProjection,notificationFilter:state.notificationFilter,microphone:state.micState,lastNewTiming:state.lastNewTiming}};const response=await fetch('/snapshot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(response.ok){const a=document.createElement('a');a.href=URL.createObjectURL(await response.blob());a.download='riverview-snapshot.zip';a.click();}}
async function load(){const auth=await fetch('/session',{method:'POST'});if(!auth.ok)return;const residents=await jsonFetch('/api/residents');(residents.residents||[]).forEach(r=>residentProfiles[r.resident_id]=r);renderApp();await loadConversations();}
function startEvents(){if(!window.EventSource)return;const stream=new EventSource('/api/events?after='+(state.cursor||0));stream.onmessage=e=>{state.cursor=Number(e.lastEventId||state.cursor||0);if(state.primaryView==='activity')loadActivity(false);else if(state.primaryView==='conversations'&&state.activeConversationId)activateConversation(state.activeConversationId);};stream.onerror=()=>{stream.close();setTimeout(startEvents,1500);};}
document.querySelectorAll('[data-view]').forEach(x=>x.addEventListener('click',()=>setView(x.dataset.view)));$('menu').onclick=()=>{state.railOpen=!state.railOpen;persist();renderApp()};$('snapshot').onclick=captureSnapshot;$('cme-hud').onclick=()=>location.href='/cme';if(window.speechSynthesis){refreshVoices();speechSynthesis.onvoiceschanged=refreshVoices;}mermaid.initialize({startOnLoad:false,securityLevel:'strict'});load().then(startEvents);
</script></body></html>'''
